breach.segment:
// PostgreSQL engine marker: excludes MySQL / SQL Server instances that share these metrics
WHERE pg > 0 AND mem_n > 0
// memory/utilization excludes buffer/cache, so sustained values near 1 are real pressure
| EVAL mem_avg_pct = ROUND(mem_sum / mem_n * 100.0, 1),
       mem_peak_pct = ROUND(mem_peak * 100.0, 1)
// Shared-core db-f1-micro instances (~0.6 GB) report memory/usage pinned at the quota,
// which reads as a permanent 100% regardless of load, so they are excluded.
// Instances with no memory/quota sample in the window are kept, so a missing quota
// never silences the rule.
| WHERE quota IS NULL OR quota >= 1000000000
// Minimum samples: require ~5 minutes of data so a single late sample cannot trigger
| WHERE mem_n >= 5
// Alert threshold: average memory utilization (percent) over the rule window
| WHERE mem_avg_pct >= 90
| KEEP database_id, mem_avg_pct, mem_peak_pct, mem_n
| SORT mem_avg_pct DESC
| LIMIT 100
